<?php require __DIR__.'/../bootstrap.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['ok'=>false],405);verify_csrf();$uid=(int)current_user()['id'];$a=(string)post('action');$c=trim((string)post('content',''));if($c==='')json_response(['ok'=>false,'error'=>'Empty content'],422);if($a==='task'){if(plan_limit_reached('tasks',$uid))json_response(['ok'=>false,'error'=>'Task limit reached. Upgrade your plan.'],429);db()->prepare('INSERT INTO tasks(user_id,title,description,status,priority,created_at,updated_at) VALUES(?,?,?,\'Todo\',\'Medium\',NOW(),NOW())')->execute([$uid,mb_substr($c,0,220),'Created from AI response.']);increment_counter('tasks_created_counter');json_response(['ok'=>true,'url'=>'/tasks/']);}if($a==='note'){if(plan_limit_reached('notes',$uid))json_response(['ok'=>false,'error'=>'Note limit reached. Upgrade your plan.'],429);db()->prepare('INSERT INTO notes(user_id,title,content,created_at,updated_at) VALUES(?,?,?,NOW(),NOW())')->execute([$uid,'AI Note', $c]);increment_counter('notes_created_counter');json_response(['ok'=>true,'url'=>'/notes/']);}if($a==='project'){if(plan_limit_reached('projects',$uid))json_response(['ok'=>false,'error'=>'Project limit reached. Upgrade your plan.'],429);db()->prepare('INSERT INTO projects(user_id,name,description,status,created_at,updated_at) VALUES(?,?,?,\'Planning\',NOW(),NOW())')->execute([$uid,mb_substr($c,0,180),$c]);increment_counter('projects_created_counter');json_response(['ok'=>true,'url'=>'/projects/']);}json_response(['ok'=>false,'error'=>'Unknown action'],400);